def count_equal(values, target):
    count = 0
    for value in values:
        if value == target:
            count += 1
    return count

print(count_equal([], 4))
print(count_equal([4], 4))
print(count_equal([4, 4], 4))
print(count_equal([3, 5], 4))

def count_pass_wrong(scores):
    count = 0
    for score in scores:
        if score > 80:
            count += 1
    return count

print(count_pass_wrong([90, 100]))
print(count_pass_wrong([80]))

def largest_index(values):
    if len(values) == 0:
        return -1
    best_index = 0
    i = 1
    while i < len(values):
        if values[i] > values[best_index]:
            best_index = i
        i += 1
    return best_index

print(largest_index([]))
print(largest_index([-5]))
print(largest_index([-8, -3, -3]))

def count_until_limit(values, target, limit):
    if limit == 0:
        return 0
    count = 0
    for value in values:
        if value == target:
            count += 1
            if count == limit:
                return count
    return count

print(count_until_limit([], 2, 3))
print(count_until_limit([2, 2, 5, 2], 2, 2))
print(count_until_limit([2, 2], 2, 0))
print(count_until_limit([2, 5], 2, 5))

def mismatch_index(expected, actual):
    i = 0
    while i < len(expected):
        if expected[i] != actual[i]:
            return i
        i += 1
    return -1

print(mismatch_index([], []))
print(mismatch_index([2, 0], [2, 1]))
print(mismatch_index([3, 3], [3, 3]))
